def maxDistance(position: list[int], m: int) -> int:
    position.sort()
    lo, hi = 1, position[-1] - position[0]
    ans = 1
    while lo <= hi:
        mid = (lo + hi) // 2
        count = 1
        last = position[0]
        for p in position[1:]:
            if p - last >= mid:
                count += 1
                last = p
        if count >= m:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1
    return ans

